import React, { useEffect, useState } from 'react';
import { Container, Spinner, Alert, Card, Button, Form } from 'react-bootstrap';
import { couchCastSocket as socket } from '../../socket';
import { toast } from 'react-toastify'
import { useNavigate } from 'react-router-dom';

// 🎮 Import your mobile screens
import CouchCastScoreboard from './CouchCastScoreboard.jsx';
import CouchCastPromptSelection from './CouchCastPromptSelection.jsx';
import CouchCastWritingPlayer from './CouchCastWritingPlayer.jsx';
import CouchCastJudging from './CouchCastJudging.jsx'; // 👈 IMPORTED OUR JUDGING COMPONENT
import { CouchCastPausedOverlay } from './CouchCastCasterControls.jsx';
import { useSetBackgroundTheme, couchCastTheme } from '../Menu/backgroundTheme.js';
import { playChime } from '../../chime.js';
import { fillBlank } from './fillBlank.js';
import { getMyAvatar } from '../../avatars.jsx';

export default function CouchCastPlayerSetup({ roomCode, playerName }) {
    const [gameState, setGameState] = useState('joining');
    const navigate = useNavigate();
    const [roomData, setRoomData] = useState(null);

    // 🎨 Background matches the room's card deck
    useSetBackgroundTheme(couchCastTheme(roomData?.expansion));
    const [playerData, setPlayerData] = useState(null);
    const [error, setError] = useState('');
    
    const [roundResults, setRoundResults] = useState(null);
    const [submissions, setSubmissions] = useState([]); // 👈 Added state to hold the anonymous answers for the judge
    const [retryName, setRetryName] = useState('');

useEffect(() => {
        // 1. Generate or grab a persistent Player ID for backend reconnection
        let pId = localStorage.getItem('templePlayerId');
        if (!pId) {
            pId = 'player_' + Math.random().toString(36).substr(2, 9);
            localStorage.setItem('templePlayerId', pId);
        }
        
        // 2. NEW LISTENER FOR THE TOAST!
        const handleJoinError = (errorMessage) => {
            toast.error(errorMessage, {
                toastId: 'joinError', // the same message never stacks
                position: "top-center",
                autoClose: 4000
            });
            // Stop the spinner and let them know there's an error
            setError(errorMessage);
            setGameState('name_retry');
        };
        
        socket.on('joinError', handleJoinError);
        
        // 🚨 Connection logic: one named listener, removed on cleanup, so a re-mount never sends joinRoom twice
        const joinMyRoom = () => socket.emit('joinRoom', { roomCode, playerName, playerId: pId, avatar: getMyAvatar() });
        socket.on('connect', joinMyRoom);
        if (socket.connected) joinMyRoom();
        else socket.connect();

        // 3. Socket listeners
        const handleSync = (payload) => {
            setGameState(payload.gameState);
            setRoomData(payload.roomData);
            setPlayerData(payload.playerStatus);
            if (payload.submissions) setSubmissions(payload.submissions);
            if (payload.roundResults) setRoundResults(payload.roundResults);
        };

        const handleRoomUpdate = (room) => {
            setRoomData(room);
            setGameState(room.gameState);
            if (room.players[socket.id]) {
                setPlayerData(room.players[socket.id]);
            }
        };

        const handleError = (msg) => {
            setError(msg);
            setGameState('error');
        };

        const handleStartJudging = (data) => {
            setGameState(data.gameState);
            setSubmissions(data.submissions);
        };

        const handleRoundEnded = (data) => {
            setGameState(data.gameState);
            setRoundResults({
                winner: data.winner,
                winningSubmission: data.winningSubmission,
                nextHostName: data.nextHostName,
                isGameOver: data.isGameOver
            });
        };

        // The TV started a different game: this one is over
        const handleRoomClosed = ({ message }) => {
            navigate('/home', { state: { toastMessage: message || 'That game has ended.' } });
        };

        socket.on('room_closed', handleRoomClosed);
        socket.on('sync_game_state', handleSync);
        socket.on('room_updated', handleRoomUpdate);
        socket.on('errorMsg', handleError);
        socket.on('start_judging', handleStartJudging);
        socket.on('round_ended', handleRoundEnded);

        return () => {
            socket.off('connect', joinMyRoom);
            socket.off('joinError', handleJoinError); // 👈 Cleaned up here!
            socket.off('sync_game_state', handleSync);
            socket.off('room_closed', handleRoomClosed);
            socket.off('room_updated', handleRoomUpdate);
            socket.off('errorMsg', handleError);
            socket.off('start_judging', handleStartJudging);
            socket.off('round_ended', handleRoundEnded); 
        };
    }, [roomCode, playerName]);

    // 🔔 Chime when it becomes this player's turn to do something
    const myTurn = (() => {
        if (!roomData || !playerData) return null;
        const amJudge = playerData.isPlayerHost;
        if (gameState === 'prompt_selection') return amJudge ? 'pick-prompt' : null;
        if (gameState === 'writing') return !amJudge && !playerData.hasSubmitted ? 'answer' : null;
        if (gameState === 'judging') return amJudge && submissions.length > 0 ? 'crown-winner' : null;
        return null;
    })();
    const turnKey = myTurn ? `${myTurn}-${roomData.currentRound}` : null;

    useEffect(() => {
        if (turnKey) playChime();
    }, [turnKey]);

    const handleStartGame = () => {
        socket.emit('showRules', { roomCode });
    };

    // ==========================================
    // RENDER VIEWS BASED ON GAME STATE
    // ==========================================

    // The Retry Screen
    if (gameState === 'name_retry') {
        return (
            <Container className="mt-5 d-flex justify-content-center">
                <Card className="text-center shadow-sm w-100 border-0" style={{ maxWidth: '400px', backgroundColor: '#f8f9fa' }}>
                    <Card.Body className="p-4">
                        <Alert variant="warning" className="fw-bold shadow-sm">
                            {error}
                        </Alert>
                        <h5 className="mb-3 text-dark">Try a different name:</h5>
                        
                        <Form.Control 
                            type="text" 
                            placeholder="New Player Name" 
                            value={retryName} 
                            onChange={(e) => setRetryName(e.target.value)}
                            className="mb-4 text-center fs-5 shadow-sm"
                            autoFocus
                        />
                        
                        <Button 
                            variant="primary" 
                            size="lg" 
                            className="w-100 fw-bold shadow-sm"
                            disabled={!retryName.trim()} // Prevents joining with a blank name
                            onClick={() => {
                                // Put the spinner back on
                                setGameState('joining'); 
                                
                                // Fire the exact same join event, but with the NEW name
                                socket.emit('joinRoom', { 
                                    roomCode: roomCode, 
                                    playerName: retryName.trim(), 
                                    playerId: localStorage.getItem('templePlayerId'),
                                    avatar: getMyAvatar(),
                                });
                            }}
                        >
                            Join Room
                        </Button>
                    </Card.Body>
                </Card>
            </Container>
        );
    }

    if (gameState === 'error') {
        return (
            <Container className="mt-5 text-center d-flex justify-content-center">
                <Alert variant="danger" className="fw-bold shadow-sm" style={{ maxWidth: '400px'}}>
                    {error}
                </Alert>
            </Container>
        );
    }

    if (gameState === 'joining' || !roomData || !playerData) {
        return (
            <Container className="mt-5 text-center">
                <Spinner animation="border" variant="primary" style={{ width: '3rem', height: '3rem' }} />
                <h4 className="mt-3 text-muted">Connecting to room {roomCode}...</h4>
            </Container>
        );
    }

    const isHost = playerData.isPlayerHost;
    const hostPlayer = roomData.hostId ? roomData.players[roomData.hostId] : null;
    const hostName = hostPlayer ? hostPlayer.name : 'the host';

    // ⏸️ The caster paused the game: "Paused" covers whatever this phone was showing
    const renderPhase = () => {
        switch (gameState) {
            case 'lobby':
                return (
                    <Container className="mt-5 d-flex justify-content-center">
                        <Card className="text-center shadow-sm w-100 border-0" style={{ maxWidth: '400px', backgroundColor: '#f8f9fa' }}>
                            <Card.Body className="p-4">
                                <h2 className="text-primary fw-bold mb-3">You're In!</h2>
                                <p className="fs-6 text-muted mb-4">Look up at the TV.</p>
                            
                                {isHost ? (
                                    <div className="p-3 border border-warning rounded bg-white shadow-sm">
                                        <p className="fw-bold text-dark mb-3">👑 You are the Room Leader</p>
                                        <Button variant={roomData.expansion === 'halloween' ? 'success' : 'primary'} size="lg" className="w-100 fw-bold py-3 fs-5 shadow-sm" onClick={handleStartGame}>
                                            All in!
                                        </Button>
                                    </div>
                                ) : (
                                    <div className="p-3 border border-dashed rounded bg-light text-muted fs-6">
                                        Waiting for <strong>{hostName}</strong> to start the game...
                                    </div>
                                )}
                            </Card.Body>
                        </Card>
                    </Container>
                );

            case 'rules':
                return (
                    <Container className="mt-5 pt-4 text-center">
                        <h1 className="text-primary fw-bold mb-3">Welcome to Couch Cast!</h1>
                        <h4 className="text-muted fw-normal">Keep your eyes on the TV to learn how to play.</h4>
                        <Spinner animation="grow" variant="warning" className="mt-5" />
                    </Container>
                );

            case 'prompt_selection':
                return (
                    <CouchCastPromptSelection 
                        isJudge={isHost} 
                        judgeName={hostName} 
                        roomCode={roomCode} 
                        prompts={roomData.promptOptions} 
                        endTime={roomData.endTime}
                    />
                );

            case 'writing':
                return (
                    <CouchCastWritingPlayer 
                        roomCode={roomCode}
                        currentPrompt={roomData.currentPrompt}
                        endTime={roomData.endTime}
                        isJudge={isHost}
                        hasSubmitted={playerData.hasSubmitted}
                        hasUsedWriteIn={!!playerData.hasUsedWriteIn}
                        promptOptions={roomData.promptOptions}
                        judgeStars={roomData.judgeStars}
                    />
                );

            case 'judging':
                 // 👈 WIRED UP THE JUDGE CONTROLLER
                 return (
                     <CouchCastJudging 
                         roomCode={roomCode} 
                         isJudge={isHost} 
                         currentPrompt={roomData.currentPrompt} 
                         endTime={roomData.endTime}
                         submissions={submissions} 
                         expansion={roomData.expansion}
                     />
                 );

            case 'winner_reveal': {
                 // Every phone shows this round's winning card (no more "look at the TV")
                 const didIWin = roundResults?.winner?.id === playerData.id;
                 const winnerName = roundResults?.winningSubmission?.playerName || roundResults?.winner?.name || 'Someone';
                 const card = roundResults?.winningSubmission
                     ? fillBlank(roomData.currentPrompt, roundResults.winningSubmission.answer)
                     : null;
             
                 return (
                     <Container className="mt-5 d-flex justify-content-center">
                         <Card className={`text-center shadow-sm w-100 border-0 ${didIWin ? 'bg-success text-white' : 'bg-light'}`} style={{ maxWidth: '400px' }}>
                             <Card.Body className="p-4 p-sm-5">
                                 <h1 className="display-1 mb-2">{didIWin ? '🏆' : '🎉'}</h1>
                                 <h2 className={`fw-bold mb-3 ${didIWin ? '' : 'text-primary'}`}>
                                     {didIWin ? 'You Won!' : `${winnerName} wins!`}
                                 </h2>

                                 {card && (
                                     <div className={`rounded p-3 mb-3 text-start fs-5 ${didIWin ? 'bg-white text-dark' : 'bg-white border'}`}>
                                         {card.hasBlank ? (
                                             <>
                                                 {card.before}<strong className="text-primary">{card.answer}</strong>{card.after}
                                             </>
                                         ) : (
                                             <>
                                                 <div className="text-muted mb-2">{card.before}</div>
                                                 <strong className="text-primary">{card.answer}</strong>
                                             </>
                                         )}
                                     </div>
                                 )}

                                 <p className={`mb-0 ${didIWin ? '' : 'text-muted'}`}>
                                     {didIWin ? 'The judge loved your answer.' : '+100 points'}
                                 </p>
                             </Card.Body>
                         </Card>
                     </Container>
                 );
            }

            case 'scoreboard':
                // The players just wait here passively. The backend timer will automatically 
                // kick everyone back to 'prompt_selection' after a few seconds!
                return (
                    <CouchCastScoreboard 
                        playerData={playerData} 
                        players={Object.values(roomData.players)} 
                        isGameOver={roundResults?.isGameOver}
                    />
                );

            default:
                return (
                    <Container className="mt-5 text-center">
                        <Spinner animation="grow" variant="warning" />
                        <h4 className="mt-3 text-muted">Wait for it...</h4>
                    </Container>
                );
        }
    };

    return (
        <>
            {renderPhase()}
            {roomData.isPaused && <CouchCastPausedOverlay />}
        </>
    );
}